import { Controller, Get, Post, Patch, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const EVIDENCE_TYPES = ['통장', '카드', '현금영수증', '전자세금계산서'];

function idOf(value: unknown, label: string): string {
  if (typeof value === 'number' && Number.isInteger(value) && value > 0) {
    return String(value);
  }
  if (typeof value === 'string' && /^[0-9]+$/.test(value)) {
    return value;
  }
  throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값이 올바르지 않습니다.');
}

@Controller('api/v1')
export class FnSfr00801Controller {
  @Patch('/journal-vouchers/:journalVoucherId')
  async updateJournalVoucher(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const voucherId = idOf(req.params['journalVoucherId'], '전표 ID');
    const itemId = idOf(data['managementItemId'], '관리항목');
    const itemValue = data['managementItemValue'];
    if (typeof itemValue !== 'string' || itemValue.trim() === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '관리항목 값을 입력하세요.');
    }
    return transaction(async (db) => {
      const vouchers = await db.query(
        'SELECT status FROM journal_voucher WHERE journal_voucher_id = CAST(:voucherId AS bigint)',
        { voucherId },
      );
      if (vouchers.length === 0) {
        throw new ApiError(404, 'JOURNAL_VOUCHER_NOT_FOUND', '전표를 찾을 수 없습니다.');
      }
      if (vouchers[0].status === '마감') {
        throw new ApiError(409, 'JOURNAL_VOUCHER_CLOSED', '마감된 전표는 수정할 수 없습니다. 승인 해제 등 정해진 절차를 먼저 진행하세요.');
      }
      const items = await db.query(
        'SELECT management_item_id FROM management_item WHERE management_item_id = CAST(:itemId AS bigint)',
        { itemId },
      );
      if (items.length === 0) {
        throw new ApiError(404, 'NOT_FOUND', '관리항목을 찾을 수 없습니다.');
      }
      await db.execute(
        'UPDATE voucher_line SET management_item_id = CAST(:itemId AS bigint), management_item_value = :itemValue, updated_at = now() WHERE journal_voucher_id = CAST(:voucherId AS bigint)',
        { itemId, itemValue, voucherId },
      );
      await db.execute(
        'UPDATE journal_voucher SET updated_at = now() WHERE journal_voucher_id = CAST(:voucherId AS bigint)',
        { voucherId },
      );
      return { journalVoucherId: Number(voucherId) };
    });
  }

  @Post('/journal-vouchers/change-evidence')
  @HttpCode(200)
  async changeJournalVoucherEvidence(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const rawIds = data['journalVoucherIds'];
    if (!Array.isArray(rawIds) || rawIds.length === 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '변경할 전표를 선택하세요.');
    }
    const evidenceType = data['evidenceType'];
    if (typeof evidenceType !== 'string' || evidenceType === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '증빙 유형을 선택하세요.');
    }
    if (!EVIDENCE_TYPES.includes(evidenceType)) {
      throw new ApiError(422, 'EVIDENCE_TYPE_INVALID', '증빙 유형은 통장, 카드, 현금영수증, 전자세금계산서만 허용합니다.');
    }
    const params: Record<string, unknown> = { evidenceType };
    const holders: string[] = [];
    rawIds.forEach((raw, index) => {
      params['id' + index] = idOf(raw, '전표 ID');
      holders.push('CAST(:id' + index + ' AS bigint)');
    });
    const idList = holders.join(', ');
    return transaction(async (db) => {
      const closed = await db.query(
        "SELECT journal_voucher_id FROM journal_voucher WHERE status = '마감' AND journal_voucher_id IN (" + idList + ')',
        params,
      );
      if (closed.length > 0) {
        throw new ApiError(409, 'JOURNAL_VOUCHER_CLOSED', '마감된 전표는 증빙내역을 변경할 수 없습니다.');
      }
      const changed = await db.execute(
        'UPDATE journal_voucher SET evidence_type = :evidenceType, updated_at = now() WHERE journal_voucher_id IN (' + idList + ')',
        params,
      );
      return { changedCount: Number(changed) };
    });
  }

  @Post('/journal-vouchers/:journalVoucherId/release-approval')
  @HttpCode(200)
  async releaseJournalVoucherApproval(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const voucherId = idOf(req.params['journalVoucherId'], '전표 ID');
    return transaction(async (db) => {
      const vouchers = await db.query(
        'SELECT status FROM journal_voucher WHERE journal_voucher_id = CAST(:voucherId AS bigint)',
        { voucherId },
      );
      if (vouchers.length === 0) {
        throw new ApiError(404, 'JOURNAL_VOUCHER_NOT_FOUND', '전표를 찾을 수 없습니다.');
      }
      if (vouchers[0].status !== '승인') {
        throw new ApiError(409, 'JOURNAL_VOUCHER_NOT_APPROVED', '승인 상태의 전표만 승인 해제할 수 있습니다.');
      }
      await db.execute(
        "UPDATE journal_voucher SET status = '승인해제', updated_at = now() WHERE journal_voucher_id = CAST(:voucherId AS bigint)",
        { voucherId },
      );
      return { status: '승인해제' };
    });
  }

  @Get('/journal-vouchers/:journalVoucherId/print')
  async printJournalVoucher(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE, '임직원');
    const voucherId = idOf(req.params['journalVoucherId'], '전표 ID');
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT voucher_no AS "voucherNo", voucher_date AS "voucherDate", debit_total AS "debitTotal", credit_total AS "creditTotal" FROM journal_voucher WHERE journal_voucher_id = CAST(:voucherId AS bigint)',
        { voucherId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'JOURNAL_VOUCHER_NOT_FOUND', '전표를 찾을 수 없습니다.');
      }
      return rows[0];
    });
  }
}

