import { useState } from 'react';
import { call, Badge, Band, DataTable, DateText, Drawer, Field, Form, LookupSelect, Num, Pairs, Select, Tiles, TextInput } from '../kit';
import type { PageProps, Row } from '../kit';

const EVIDENCE_OPTIONS: [string, string][] = [
  ['통장', '통장'],
  ['카드', '카드'],
  ['현금영수증', '현금영수증'],
  ['전자세금계산서', '전자세금계산서'],
];

type Panel = { kind: 'create' } | { kind: 'item'; row: Row } | { kind: 'evidence' } | { kind: 'print'; data: Row } | undefined;

export default function FnSfr00801Page({ role, notify }: PageProps) {
  // 조회 API가 없어 이 화면에서 처리한 전표를 목록으로 보인다
  const [rows, setRows] = useState<Row[]>([]);
  const [panel, setPanel] = useState<Panel>(undefined);
  const [selected, setSelected] = useState<string[]>([]);
  const [resolutionId, setResolutionId] = useState<number | string>('');
  const [itemId, setItemId] = useState<number | string>('');
  const [itemValue, setItemValue] = useState('');
  const [evidenceType, setEvidenceType] = useState('');

  const patchRow = (id: unknown, values: Row) => {
    setRows(rows.map((r) => (r.journalVoucherId === id ? { ...r, ...values } : r)));
  };

  const toggle = (id: string) => {
    setSelected(selected.includes(id) ? selected.filter((s) => s !== id) : [...selected, id]);
  };

  const create = async () => {
    if (resolutionId === '') {
      throw new Error('원천 결의서를 선택하세요.');
    }
    const res = await call('POST', '/journal-vouchers', role, { expenseResolutionId: resolutionId });
    setRows([{ journalVoucherId: res.journalVoucherId, voucherNo: res.voucherNo, status: '승인', evidenceType: '' }, ...rows]);
    setResolutionId('');
    setPanel(undefined);
    notify('전표를 입력했습니다.');
  };

  const updateItem = async (row: Row) => {
    if (itemId === '' || itemValue.trim() === '') {
      throw new Error('관리항목과 관리항목 값을 입력하세요.');
    }
    await call('PATCH', '/journal-vouchers/' + row.journalVoucherId, role, { managementItemId: itemId, managementItemValue: itemValue });
    setItemId('');
    setItemValue('');
    setPanel(undefined);
    notify('관리항목을 변경했습니다.');
  };

  const changeEvidence = async () => {
    if (selected.length === 0) {
      throw new Error('변경할 전표를 선택하세요.');
    }
    if (evidenceType === '') {
      throw new Error('증빙 유형을 선택하세요.');
    }
    const res = await call('POST', '/journal-vouchers/change-evidence', role, {
      journalVoucherIds: selected.map((s) => Number(s)),
      evidenceType,
    });
    setRows(rows.map((r) => (selected.includes(String(r.journalVoucherId)) ? { ...r, evidenceType } : r)));
    setSelected([]);
    setEvidenceType('');
    setPanel(undefined);
    notify('증빙내역을 ' + res.changedCount + '건 변경했습니다.');
  };

  const release = async (row: Row) => {
    const res = await call('POST', '/journal-vouchers/' + row.journalVoucherId + '/release-approval', role, {});
    patchRow(row.journalVoucherId, { status: res.status });
    notify('승인을 해제했습니다.');
  };

  const print = async (row: Row) => {
    try {
      const data = await call('GET', '/journal-vouchers/' + row.journalVoucherId + '/print', role);
      setPanel({ kind: 'print', data });
    } catch (e) {
      notify(e instanceof Error ? e.message : '출력하지 못했습니다.');
    }
  };

  const approved = rows.filter((r) => r.status === '승인').length;

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>처리 현황</h2>
        <Tiles items={[['처리한 전표', <Num value={rows.length} />], ['승인 전표', <Num value={approved} />], ['선택한 전표', <Num value={selected.length} />]]} />
      </section>
      <section className="box span-12">
        <h2>전표</h2>
        <Band total={rows.length}>
          <button onClick={() => setPanel({ kind: 'create' })}>전표 입력</button>
          <button onClick={() => setPanel({ kind: 'evidence' })}>증빙내역 일괄 변경</button>
        </Band>
        <DataTable
          rows={rows}
          empty="처리한 전표가 없습니다."
          columns={[
            {
              key: 'select',
              label: '선택',
              render: (r) => (
                <input type="checkbox" checked={selected.includes(String(r.journalVoucherId))} onChange={() => toggle(String(r.journalVoucherId))} />
              ),
            },
            { key: 'voucherNo', label: '전표번호' },
            { key: 'evidenceType', label: '증빙 유형' },
            { key: 'status', label: '전표 상태', render: (r) => <Badge value={r.status} /> },
            {
              key: 'actions',
              label: '처리',
              render: (r) => (
                <span>
                  {r.status !== '마감' && (
                    <button onClick={() => setPanel({ kind: 'item', row: r })}>관리항목 변경</button>
                  )}
                  {r.status === '승인' && (
                    <button onClick={() => release(r)}>승인 해제</button>
                  )}
                  <button onClick={() => print(r)}>출력</button>
                </span>
              ),
            },
          ]}
        />
      </section>
      {panel && panel.kind === 'create' && (
        <Drawer title="전표 입력" onClose={() => setPanel(undefined)}>
          <Form onSubmit={create} submit="전표 생성">
            <Field label="원천 결의서" required wide>
              <LookupSelect table="expense_resolution" role={role} value={resolutionId} onChange={setResolutionId} />
            </Field>
          </Form>
        </Drawer>
      )}
      {panel && panel.kind === 'item' && (
        <Drawer title="전표 관리항목 변경" onClose={() => setPanel(undefined)}>
          <Form onSubmit={() => updateItem(panel.row)} submit="변경">
            <Field label="관리항목" required wide>
              <LookupSelect table="management_item" role={role} value={itemId} onChange={setItemId} />
            </Field>
            <Field label="관리항목 값" required wide>
              <TextInput value={itemValue} onChange={setItemValue} />
            </Field>
          </Form>
        </Drawer>
      )}
      {panel && panel.kind === 'evidence' && (
        <Drawer title="증빙내역 일괄 변경" onClose={() => setPanel(undefined)}>
          <Form onSubmit={changeEvidence} submit="일괄 변경" note={'선택한 전표 ' + selected.length + '건에 적용합니다.'}>
            <Field label="증빙 유형" required wide>
              <Select value={evidenceType} onChange={setEvidenceType} options={EVIDENCE_OPTIONS} />
            </Field>
          </Form>
        </Drawer>
      )}
      {panel && panel.kind === 'print' && (
        <Drawer title="전표 출력" onClose={() => setPanel(undefined)}>
          <Pairs
            items={[
              ['전표번호', String(panel.data.voucherNo ?? '')],
              ['전표일자', <DateText value={panel.data.voucherDate} />],
              ['차변 합계', <Num value={panel.data.debitTotal} />],
              ['대변 합계', <Num value={panel.data.creditTotal} />],
            ]}
          />
          <button onClick={() => window.print()}>인쇄</button>
        </Drawer>
      )}
    </div>
  );
}
